$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78NativeFunctionalResults";$scratch="$root\M78NativeEditorBuild";$exe="$root\Build\Release\m78_combined-v2_editor.exe";$name='m78-native-final-editor-build'
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if(Test-Path $scratch){throw 'Preserve owned editor build'};if(Test-Path $exe){throw 'Preserve editor executable'};if((Get-PSDrive C).Free -lt 64MB){throw 'Bounded editor build headroom absent'};$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-native-editor-manifest.json").Content|ConvertFrom-Json;if((Get-FileHash $m.libraryPath).Hash.ToLower() -ne $m.librarySHA256){throw 'Frozen final library changed'};foreach($row in $m.sources){if((Get-FileHash (Join-Path "$root\Source" $row.path)).Hash.ToLower() -ne $row.sha256){throw 'Current editor source changed'}}
 New-Item -ItemType Directory $scratch|Out-Null;Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$rows=@();$objects=@();$ErrorActionPreference='Continue'
 foreach($unit in $m.units){if((Get-PSDrive C).Free -lt 36MB){throw 'Insufficient remaining bounded editor link reserve'};$obj="$scratch\$($unit.objectName)";$flags=[string]$unit.flags;$flags=[regex]::Replace($flags,'/Fo"[^"]*"',('/Fo"'+$obj+'"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);$flags=[regex]::Replace($flags,'/Fd"[^"]*"',('/Fd"'+$scratch+'\compile.pdb"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);$flags='/I"'+$root+'\M78ContinuationBuild\combined-v2\source\src" '+$flags;$rsp="$scratch\$($unit.objectName).rsp";[IO.File]::WriteAllText($rsp,$flags,[Text.UTF8Encoding]::new($false));$log="$out\$name-$($unit.objectName).log";& cl.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Scoped unchanged editor compilation failed'};$rows+=@{source=$unit.path;sourceSHA256=$unit.sha256;object=$obj;objectSHA256=(Get-FileHash $obj).Hash.ToLower();compilerResponse=$flags};$objects+=$obj}
 $link=[string]$m.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB',('"'+$m.libraryPath+'"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$scratch+'\link.pdb"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$scratch+'\import.lib"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase);foreach($obj in $objects){$file=[IO.Path]::GetFileName($obj);$link=[regex]::Replace($link,[regex]::Escape('JUDAS_EDITOR.DIR\RELEASE\'+$file),('"'+$obj+'"'),[Text.RegularExpressions.RegexOptions]::IgnoreCase)};$rsp="$scratch\link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$out\$name-link.log";[IO.File]::WriteAllText($log,'');& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Scoped final editor link failed'}
 @{scope=$m.scope;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();librarySHA256=$m.librarySHA256;compiles=$rows;linkerResponse=$link;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 7|Set-Content "$out\$name.json" -Encoding UTF8;Upload "$out\$name.json" "$name.json"
}catch{[string]$_.Exception.Message|Set-Content "$out\$name-error.txt";Upload "$out\$name-error.txt" "$name-error.txt";exit 1}
